core_shell_source:
function Invoke-CargoTest([string[]] $Arguments) {
  & cargo nextest run --locked @Arguments
  if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
}

switch ($env:TEST_SHARD) {
  "core-service-1" {
    Invoke-CargoTest @("-p", "portcove-core", "--partition", "hash:1/2", "service::")
  }
  "core-service-2" {
    Invoke-CargoTest @("-p", "portcove-core", "--partition", "hash:2/2", "service::")
  }
  "core-recovery" {
    Invoke-CargoTest @("-p", "portcove-core", "cancellation::")
    Invoke-CargoTest @("-p", "portcove-core", "database::")
    Invoke-CargoTest @("-p", "portcove-core", "import_execution::")
    Invoke-CargoTest @("-p", "portcove-core", "library_move::")
  }
  "core-other-1" {
    Invoke-CargoTest @("-p", "portcove-core", "--partition", "hash:1/2", "--", "--skip", "service::", "--skip", "cancellation::", "--skip", "database::", "--skip", "import_execution::", "--skip", "library_move::")
  }
  "core-other-2" {
    Invoke-CargoTest @("-p", "portcove-core", "--partition", "hash:2/2", "--", "--skip", "service::", "--skip", "cancellation::", "--skip", "database::", "--skip", "import_execution::", "--skip", "library_move::")
  }
  default { throw "Unknown Rust test shard: $env:TEST_SHARD" }
}
